from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(5,'fractions','Fractions, quotients et comparaisons','1 · Nombres et calculs',
'Un nombre · Plusieurs écritures · Dénominateur commun',
['Comprendre une fraction comme nombre quotient.','Passer entre des écritures équivalentes.','Comparer et placer des fractions.'],['Multiples, divisions et droites graduées.'],[
page(1,'Un quotient est un nombre',
bloc('definition',r'Pour $b\ne0$, le quotient $a/b$ est le nombre qui, multiplié par $b$, donne $a$. Une fraction est un quotient de deux entiers, avec un dénominateur non nul. Le numérateur compte des parts ; le dénominateur indique le partage de l’unité.'),
r'@FIG:cours-fractions@',
bloc('propriete',r'Multiplier ou diviser numérateur et dénominateur par un même nombre non nul conserve la valeur : $\frac34=\frac68=\frac{15}{20}$. Une fraction peut être plus grande que 1 : $\frac74=1+\frac34$.'),
bloc('exemple',r'$1{,}25=\frac{125}{100}=\frac54=1+\frac14=125\,\%$. Ce sont différentes écritures du même nombre. Un quotient comme $1/3$ ne possède pas d’écriture décimale finie ; $0{,}33$ n’en est qu’une approximation.')),
page(2,'Choisir une méthode de comparaison',
bloc('propriete',r'À dénominateur positif identique, la plus grande fraction a le plus grand numérateur. À numérateur positif identique, la fraction ayant le plus petit dénominateur est la plus grande.'),
bloc('savoirfaire',r'Pour comparer $\frac58$ et $\frac7{12}$, choisir un dénominateur commun : $\frac{15}{24}>\frac{14}{24}$. On peut aussi comparer à 1 ou à $1/2$ quand cela suffit.','Un même partage'),
bloc('exemple',r'Pour placer $11/4$, effectuer $11=4\times2+3$ : $\frac{11}4=2+\frac34$. Partager l’intervalle de 2 à 3 en quatre et compter trois parts.'),
bloc('attention',r'Le dénominateur ne se lit pas comme une partie indépendante du nombre. $\frac25<\frac23$ malgré $5>3$ : cinquièmes et tiers ne sont pas les mêmes parts. Ne pas comparer uniquement les chiffres.'))
],[
E('Compléter un produit',r'Quel nombre complète $7\times\,?=5$ ?',r'Par définition du quotient, c’est $\res{5/7}$. On vérifie $7\times(5/7)=5$.','Revenir au nombre quotient.','assert 7*Rational(5,7)==5'),
E('Fractions égales',r'Compléter $\frac35=\frac{\,?\,}{20}$ et $\frac47=\frac{12}{\,?\,}$.',r'On multiplie par 4 dans la première fraction et par 3 dans la seconde : $\res{12/20}$ et $\res{12/21}$.','Faire la même opération en haut et en bas.','assert Rational(3,5)==Rational(12,20) and Rational(4,7)==Rational(12,21)'),
E('Écriture décimale',r'Écrire $\frac12$, $\frac34$ et $\frac52$ sous forme décimale.',r'Les divisions donnent $\res{0{,}5}$, $\res{0{,}75}$ et $\res{2{,}5}$. Le dernier nombre dépasse 1.','Lire la fraction comme une division.','assert Rational(1,2)==Rational(".5") and Rational(3,4)==Rational(".75") and Rational(5,2)==Rational("2.5")'),
E('Même dénominateur',r'Comparer $7/11$ et $9/11$.',r'On compare le nombre de onzièmes : $7<9$, donc $\res{7/11<9/11}$.','Comparer les numérateurs.','assert Rational(7,11)<Rational(9,11)'),
E('Même numérateur',r'Comparer $5/8$ et $5/13$.',r'Les huitièmes sont plus grands que les treizièmes. En prenant cinq parts, on obtient $\res{5/8>5/13}$.','Comparer la taille des parts.','assert Rational(5,8)>Rational(5,13)'),
E('Un dénominateur commun',r'Comparer $5/6$ et $7/9$.',r'Au dénominateur 18 : $5/6=15/18$ et $7/9=14/18$. Donc $\res{5/6>7/9}$.','Choisir un multiple commun.','assert Rational(5,6)==Rational(15,18)>Rational(14,18)==Rational(7,9)'),
E('Dépasser l’unité',r'Écrire $23/6$ comme somme d’un entier et d’une fraction inférieure à 1.',r'$23=6\times3+5$, donc $\res{23/6=3+5/6}$. Le reste 5 est inférieur au dénominateur 6.','Utiliser la division euclidienne.','assert Rational(23,6)==3+Rational(5,6)'),
E('Placer des fractions',r'Placer $1/2$, $5/4$ et $7/4$ sur la droite graduée en quarts.',r'$1/2=2/4$ ; on place les points à deux, cinq et sept quarts de zéro. Le corrigé montre leurs positions.','Exprimer chaque abscisse dans le pas de graduation.','assert Rational(1,2)==Rational(2,4) and Rational(5,4)<Rational(7,4)',figure='frac-8'),
E('Des formes équivalentes',r'Écrire 0,6 comme fraction de dénominateur 10, fraction de dénominateur 5 et pourcentage.',r'$0{,}6=\res{6/10=3/5=60\,\%}$. Le pourcentage exprime une fraction sur 100.','Conserver la même valeur.','assert Rational(".6")==Rational(6,10)==Rational(3,5)==Rational(60,100)'),
E('Exact ou approché',r'$2/3=0{,}67$ est-il exact ? Justifier sans calculatrice.',r'Non : $3\times0{,}67=2{,}01$, et non 2. On peut écrire $\res{2/3\approx0{,}67}$ au centième. L’écriture exacte reste $2/3$.','Vérifier par multiplication.','assert 3*Rational(".67")==Rational("2.01") and Rational(2,3)!=Rational(".67")'),
E('Classer trois parts',r'Ranger $3/4$, $5/6$ et $7/12$ dans l’ordre croissant.',r'Au dénominateur 12, on obtient $9/12$, $10/12$ et $7/12$. Donc $\res{7/12<3/4<5/6}$.','Choisir un partage commun aux trois nombres.','assert Rational(7,12)<Rational(3,4)<Rational(5,6)'),
E('Comparer sans tout calculer',r'Comparer $11/10$ et $9/11$, puis $4/9$ et $5/8$ en utilisant 1 ou $1/2$.',r'$11/10>1>9/11$, donc le premier est plus grand. $4/9<1/2$ car $8<9$ ; $5/8>1/2$ car $5>4$. Ainsi $\res{4/9<5/8}$.','Choisir un repère simple.','assert Rational(11,10)>1>Rational(9,11) and Rational(4,9)<Rational(1,2)<Rational(5,8)'),
E('Trois recettes',r'Dans A, il y a 3 doses de sirop pour 8 doses de boisson ; dans B, 5 pour 12 ; dans C, 2 pour 5. Quelle boisson a la plus grande proportion de sirop ?',r'Les proportions sont $3/8$, $5/12$, $2/5$. Au dénominateur 120 : $45/120$, $50/120$, $48/120$. La boisson $\res B$ est la plus concentrée. On compare des proportions, malgré des quantités totales différentes.','Rapporter chaque part au total.','assert Rational(5,12)>Rational(2,5)>Rational(3,8)'),
E('Un encadrement fin',r'Trouver tous les entiers $a$ tels que $\frac23<\frac a{12}<\frac56$.',r'$2/3=8/12$ et $5/6=10/12$. Il faut $8<a<10$, donc $\res{a=9}$ seulement. Les bornes sont strictes.','Réduire les bornes au dénominateur demandé.','assert [a for a in range(15) if Rational(2,3)<Rational(a,12)<Rational(5,6)]==[9]'),
E('Deux affichages, une valeur',r'Une jauge affiche 1,5 unité, une autre $6/4$, une troisième 150 %. Expriment-elles le même nombre ? Que faut-il vérifier si on compare des remplissages ?',r'Numériquement, $\res{1{,}5=6/4=150/100}$. Pour comparer des volumes réels, il faut aussi connaître l’unité et la capacité de référence. 150 % de 2 L vaut 3 L, mais 150 % de 4 L vaut 6 L.','Distinguer nombre et grandeur de référence.','assert Rational("1.5")==Rational(6,4)==Rational(150,100) and Rational(150,100)*2==3 and Rational(150,100)*4==6')
],reperes=['Fraction et nombre quotient','Écritures équivalentes','Comparaison et droite graduée','Fractions, décimaux et pourcentages'],deco='calcul')

chapitre(6,'additions-fractions','Additionner et soustraire des fractions','1 · Nombres et calculs',
'Dénominateurs quelconques · Quantités · Partages',
['Additionner et soustraire avec un dénominateur commun.','Résoudre des problèmes de parts et de restes.','Contrôler une somme par rapport à l’unité.'],['Fractions égales et multiples.'],[
page(1,'Exprimer les parts de la même façon',
bloc('propriete',r'Pour $b>0$, $\frac ab+\frac cb=\frac{a+c}b$ et $\frac ab-\frac cb=\frac{a-c}b$. Le dénominateur indique la taille des parts ; il reste inchangé.'),
r'@FIG:cours-somme-fractions@',
bloc('savoirfaire',r'Pour $\frac34+\frac56$, utiliser le dénominateur 12 : $\frac9{12}+\frac{10}{12}=\frac{19}{12}=1+\frac7{12}$. Un multiple commun convient ; prendre un petit multiple réduit les calculs.','Changer de partage'),
bloc('attention',r'$\frac12+\frac13$ ne vaut pas $\frac25$. La somme de $1/2$ et d’un nombre positif est supérieure à $1/2$, alors que $2/5<1/2$ : ce contrôle révèle l’erreur.')),
page(2,'Interpréter les fractions',
bloc('savoirfaire',r'Prendre $a/b$ d’une quantité signifie partager cette quantité en $b$ parts égales puis en prendre $a$. Les $3/5$ de 40 valent $(40:5)\times3=24$. On peut raisonner en parts sans utiliser de règle de produit de fractions.','Fraction d’une quantité'),
bloc('exemple',r'Un trajet est parcouru pour $2/5$ le matin et $1/3$ l’après-midi, ces deux fractions portant sur le trajet entier. La part faite est $6/15+5/15=11/15$ ; il reste $1-11/15=4/15$.'),
bloc('savoirfaire',r'Lorsqu’on parle d’une fraction du reste, calculer le reste avant d’appliquer la fraction. Pour 60 L, après usage de $1/3$ du total il reste 40 L ; la moitié de ce reste vaut 20 L.','Identifier le tout'),
bloc('attention',r'Les questions de ce chapitre portent sur des fractions positives et des additions ou soustractions. Un partage peut donner une quantité non entière ; vérifier si le contexte l’autorise.'))
],[
E('Addition directe',r'Calculer $2/7+3/7$.',r'On additionne les numérateurs : $(2+3)/7=\res{5/7}$.','Garder le dénominateur commun.','assert Rational(2,7)+Rational(3,7)==Rational(5,7)'),
E('Soustraction directe',r'Calculer $9/11-4/11$.',r'On retranche quatre onzièmes à neuf onzièmes : $\res{5/11}$.','Compter les mêmes parts.','assert Rational(9,11)-Rational(4,11)==Rational(5,11)'),
E('Complément à un',r'Calculer $1-3/8$.',r'$1=8/8$, donc $8/8-3/8=\res{5/8}$.','Écrire l’entier avec le bon dénominateur.','assert 1-Rational(3,8)==Rational(5,8)'),
E('Dénominateurs multiples',r'Calculer $1/3+1/6$.',r'$1/3=2/6$. La somme vaut $3/6=\res{1/2}$.','Transformer la première fraction.','assert Rational(1,3)+Rational(1,6)==Rational(1,2)'),
E('Une part de 28',r'Calculer les $3/4$ de 28.',r'Un quart vaut $28:4=7$. Trois quarts valent $7\times3=\res{21}$.','Partager puis prendre les parts.','assert Rational(28,4)*3==21'),
E('Dénominateurs quelconques',r'Calculer $5/8+7/12$.',r'Le dénominateur commun 24 donne $15/24+14/24=\res{29/24=1+5/24}$.','Choisir un multiple commun.','assert Rational(5,8)+Rational(7,12)==Rational(29,24)'),
E('Une différence',r'Calculer $7/10-5/12$.',r'Au dénominateur 60 : $42/60-25/60=\res{17/60}$. Le résultat est positif car $7/10>5/12$.','Vérifier le sens de la différence.','assert Rational(7,10)-Rational(5,12)==Rational(17,60)'),
E('Trois termes',r'Calculer $2/3+3/4-5/6$.',r'Au dénominateur 12 : $8/12+9/12-10/12=\res{7/12}$. Les trois fractions sont réécrites avant d’opérer.','Utiliser un dénominateur commun à tous.','assert Rational(2,3)+Rational(3,4)-Rational(5,6)==Rational(7,12)'),
E('Entier et fraction',r'Calculer $3+5/6-7/4$.',r'Au dénominateur 12 : $36/12+10/12-21/12=\res{25/12=2+1/12}$.','Transformer aussi l’entier.','assert 3+Rational(5,6)-Rational(7,4)==Rational(25,12)'),
E('Retrouver une part',r'Compléter $5/9+\,?=7/6$.',r'La part manquante vaut $7/6-5/9=21/18-10/18=\res{11/18}$. Contrôle : $10/18+11/18=21/18$.','Utiliser l’opération inverse.','assert Rational(7,6)-Rational(5,9)==Rational(11,18)'),
E('Deux étapes de trajet',r'On parcourt $3/8$ d’un trajet le matin et $5/12$ du trajet entier l’après-midi. Quelle fraction reste-t-il ? Pour 144 km, quelle distance est-ce ?',r'On a fait $9/24+10/24=19/24$. Il reste $\res{5/24}$. Une part vaut $144:24=6$ km ; cinq parts valent $\res{30\ \mathrm{km}}$.','Additionner les parts du même total.','assert 1-Rational(3,8)-Rational(5,12)==Rational(5,24) and Rational(144,24)*5==30'),
E('Un budget',r'Sur un budget de 240 euros, $1/3$ sert aux transports et $3/8$ aux repas. Le reste suffit-il pour un achat de 75 euros ?',r'La part restante vaut $1-8/24-9/24=7/24$. Elle représente $(240:24)\times7=\res{70}$ euros. Il manque $\res5$ euros : l’achat ne peut pas être payé entièrement.','Passer de la fraction restante à la somme.','assert 1-Rational(1,3)-Rational(3,8)==Rational(7,24) and Rational(240,24)*7==70 and 75-70==5'),
E('Fraction du reste',r'Une citerne contient 90 L. On utilise $2/5$ du contenu, puis $1/3$ du reste. Combien reste-t-il après les deux usages ?',r'Le premier usage vaut $(90:5)\times2=36$ L. Il reste 54 L. Le second usage vaut $54:3=18$ L. Il reste donc $\res{36\ \mathrm L}$. La seconde fraction porte sur 54 L.','Actualiser la quantité de référence.','assert 90-90//5*2==54 and 54-54//3==36'),
E('Retrouver le total',r'Un ruban a été coupé : $1/4$ de sa longueur pour A, $1/3$ pour B, tous deux du ruban initial. Les 35 cm restants sont pour C. Trouver la longueur initiale.',r'Les deux premières parts valent $3/12+4/12=7/12$. Les 35 cm correspondent aux $5/12$ restants. Un douzième vaut $35:5=7$ cm ; le ruban entier mesure $\res{84\ \mathrm{cm}}$. Contrôle : $21+28+35=84$.','Retrouver la valeur d’une part élémentaire.','assert 1-Rational(1,4)-Rational(1,3)==Rational(5,12) and 35//5*12==84 and 21+28+35==84'),
E('Un partage impossible',r'Une élève promet $5/8$ d’un gâteau à un groupe et $7/12$ du même gâteau à un autre, sans chevauchement. Est-ce possible ? De quelle fraction la promesse dépasse-t-elle le gâteau ?',r'$5/8+7/12=15/24+14/24=29/24>1$. C’est impossible avec un seul gâteau. La promesse dépasse le tout de $\res{5/24}$.','Comparer le total des parts à 1.','assert Rational(5,8)+Rational(7,12)-1==Rational(5,24)')
],reperes=['Sommes et différences de fractions','Dénominateurs quelconques','Fraction d’une quantité','Reste et reconstitution d’un tout'],deco='calcul')

chapitre(7,'carres-cubes','Carrés et cubes','1 · Nombres et calculs',
'Produits répétés · Aires · Volumes · Expressions',
['Lire les puissances 2 et 3.','Connaître les carrés des entiers de 0 à 12.','Calculer une expression contenant un carré ou un cube.'],['Produits, priorités, unités d’aire et de volume.'],[
page(1,'Deux ou trois facteurs identiques',
bloc('definition',r'Le carré de $a$ est $a^2=a\times a$. Son cube est $a^3=a\times a\times a$. L’exposant compte les facteurs : $4^3=64$ et non $4\times3$. On travaille ici avec des nombres positifs ou nuls.'),
r'@FIG:cours-carre-cube@',
tableau(['$a$','0','1','2','3','4','5','6'],[['$a^2$','0','1','4','9','16','25','36']])+tableau(['$a$','7','8','9','10','11','12'],[['$a^2$','49','64','81','100','121','144']]),
bloc('exemple',r'$10^3=1000$. $25=5^2$ et $27=3^3$. On peut retrouver une base en reconnaissant une valeur connue.')),
page(2,'Calculer et donner du sens',
bloc('propriete',r'Les puissances se calculent avant les produits et les sommes : $3+2\times5^2=3+2\times25=53$. Les parenthèses restent prioritaires : $(3+2)^2=25$.'),
bloc('exemple',r'Pour $x=4$, l’expression $2x^2+3$ vaut $2\times4^2+3=35$. Réécrire les signes de multiplication facilite la substitution.'),
bloc('savoirfaire',r'L’aire d’un carré de côté $c$ est $c^2$ ; le volume d’un cube de côté $c$ est $c^3$. Si le côté est en cm, l’aire est en cm$^2$ et le volume en cm$^3$. $1$ dm$^3=(10\ \mathrm{cm})^3=1000$ cm$^3$.','Relier au dessin'),
bloc('attention',r'En général $(a+b)^2$ n’est pas égal à $a^2+b^2$. Pour $a=2$ et $b=3$, on obtient 25 d’un côté et 13 de l’autre. Un carré ne se distribue pas sur une somme.'))
],[
E('Lire un carré',r'Écrire $9^2$ comme produit puis calculer.',r'$9^2=9\times9=\res{81}$. Il y a deux facteurs 9.','Déplier la notation.','assert 9**2==81'),
E('Lire un cube',r'Calculer $4^3$.',r'$4^3=4\times4\times4=16\times4=\res{64}$.','Compter trois facteurs.','assert 4**3==64'),
E('Carrés repères',r'Donner les carrés de 0, 7, 11 et 12.',r'Ils valent $\res{0,\ 49,\ 121,\ 144}$. Ces valeurs se retrouvent dans les produits des nombres par eux-mêmes.','Utiliser les carrés à connaître.','assert [a*a for a in [0,7,11,12]]==[0,49,121,144]'),
E('Retrouver la base',r'Compléter $\,?^2=36$ et $\,?^3=1000$ avec des nombres positifs.',r'$6\times6=36$ et $10\times10\times10=1000$. Les bases sont $\res6$ et $\res{10}$.','Reconnaître les produits répétés.','assert 6**2==36 and 10**3==1000'),
E('Puissance ou produit',r'Comparer $5^3$ et $5\times3$.',r'$5^3=\res{125}$ tandis que $5\times3=\res{15}$. Les écritures ne décrivent pas le même calcul.','Distinguer exposant et facteur.','assert 5**3==125 and 5*3==15'),
E('Priorités avec un carré',r'Calculer $6+3\times4^2$.',r'Le carré vaut 16, puis le produit vaut 48. Le total est $\res{54}$.','Calculer la puissance avant le produit.','assert 6+3*4**2==54'),
E('Parenthèses et carré',r'Calculer $(8-3)^2$ et $8^2-3^2$.',r'Le premier vaut $5^2=\res{25}$. Le second vaut $64-9=\res{55}$. Les parenthèses définissent la base.','Identifier ce qui est élevé au carré.','assert (8-3)**2==25 and 8**2-3**2==55'),
E('Carré décimal',r'Calculer $1{,}5^2$ et $0{,}2^3$.',r'$1{,}5\times1{,}5=\res{2{,}25}$. $0{,}2\times0{,}2\times0{,}2=\res{0{,}008}$. Une puissance peut diminuer un nombre compris entre 0 et 1.','Multiplier les facteurs identiques.','assert Rational("1.5")**2==Rational("2.25") and Rational(".2")**3==Rational(".008")'),
E('Une substitution',r'Calculer $A=3x^2+2$ pour $x=5$, puis $B=x^3-x$ pour $x=2$.',r'$A=3\times25+2=\res{77}$ et $B=8-2=\res6$. Le coefficient 3 ne fait pas partie de la base du carré.','Remplacer la lettre avec soin.','assert 3*5**2+2==77 and 2**3-2==6'),
E('Une unité de volume',r'Combien de cm$^3$ y a-t-il dans 2 dm$^3$ ?',r'Un cube de 1 dm de côté a 10 cm de côté : $10^3=1000$ cm$^3$. Donc 2 dm$^3=\res{2000\ \mathrm{cm}^3}$.','Convertir les trois dimensions.','assert 2*10**3==2000'),
E('Un carré à carreler',r'Un sol carré a un côté de 3,2 m. Calculer son aire. Quatre paquets couvrant chacun 2,5 m$^2$ suffisent-ils ?',r'L’aire vaut $3{,}2^2=\res{10{,}24\ \mathrm{m}^2}$. Quatre paquets couvrent 10 m$^2$, ce qui ne suffit pas : il faut cinq paquets au minimum, en négligeant les pertes.','Comparer des aires dans la même unité.','assert Rational("3.2")**2==Rational("10.24") and 4*Rational("2.5")<Rational("10.24")<=5*Rational("2.5")',figure='puiss-11'),
E('Un cube de cubes',r'Un grand cube comporte six petits cubes sur chaque arête. Combien de petits cubes contient-il ? Combien contient une seule couche ?',r'Une couche contient $6^2=\res{36}$ cubes. Il y a six couches, donc $6^3=\res{216}$ cubes.','Distinguer couche et solide entier.','assert 6**2==36 and 6**3==216',figure='puiss-12'),
E('Deux cubes comparés',r'Deux cubes ont pour côtés 2 cm et 4 cm. Le second volume est-il seulement le double du premier ?',r'Les volumes valent $2^3=8$ et $4^3=64$ cm$^3$. Le second vaut $\res8$ fois le premier. Doubler chacune des trois dimensions donne $2\times2\times2=8$.','Comparer les produits des trois dimensions.','assert 4**3//2**3==8',figure='puiss-13'),
E('Réfuter une formule',r'Sami affirme que $(a+b)^2=a^2+b^2$ pour tous les nombres positifs. Choisir un contre-exemple.',r'Pour $a=1$ et $b=2$, $(1+2)^2=9$, tandis que $1^2+2^2=5$. Comme $\res{9\ne5}$, l’affirmation générale est fausse. Un seul contre-exemple suffit.','Tester des valeurs simples.','assert (1+2)**2!=1**2+2**2'),
E('Une bordure carrée',r'Un carré de côté 8 cm est entouré d’une bordure de 1 cm de large, à l’extérieur. Calculer l’aire de la bordure.',r'Le côté extérieur vaut $8+1+1=10$ cm. L’aire cherchée est $10^2-8^2=100-64=\res{36\ \mathrm{cm}^2}$. Ajouter seulement 1 au côté oublierait l’autre bord.','Soustraire l’aire intérieure à l’aire extérieure.','assert (8+2)**2-8**2==36',figure='puiss-15')
],reperes=['Notation du carré et du cube','Carrés de 0 à 12 et cube de 10','Priorités et substitution','Aires, volumes et contre-exemples'],deco='calcul')
